#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

int main(void) {
    for (int i = 1;; i++) {
        char *p = malloc(10 << 20);
        if (!p) return 1;
        memset(p, 1, 10 << 20);
        printf("holding %d MB\n", i * 10);
        fflush(stdout);
        usleep(50000);
    }
}
